#include <iostream>
#include <map>
#include <string>

int main()
{
    std::map<std::string, int> count;

    std::string word;
    while (std::cin >> word)
    {
        for (char& c : word)
            if (c >= 'A' && c <= 'Z') c = static_cast<char>(c - 'A' + 'a');
        ++count[word];
    }

    std::cout << "distinct " << count.size() << "\n";

    std::string best;
    int bestCount{ 0 };
    for (const auto& entry : count)
    {
        std::cout << entry.first << ' ' << entry.second << "\n";
        if (entry.second > bestCount)
        {
            bestCount = entry.second;
            best = entry.first;
        }
    }

    if (bestCount > 0) std::cout << "top " << best << ' ' << bestCount << "\n";
    else               std::cout << "top none 0\n";

    return 0;
}
